def evaluate(current_reputation, observation, my_history, round_num):
    # Use a moving average with alpha=0.8 (faster decay of old info).
    # Asymmetric base adjustments: +0.25 for donate, -0.25 for not donate.
    # Additional boost/penalty when reputation is extreme.
    if observation["action"] == "donate":
        add = 0.25
        # Extra boost when reputation is low (encourages recovery)
        if current_reputation < -0.5:
            add += 0.2
    else:
        add = -0.25
        # Extra penalty when reputation is high (harder to drop from good standing)
        if current_reputation > 0.8:
            add -= 0.2
    new_rep = 0.8 * current_reputation + add
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Compute own donation rate as measure of personal generosity.
    if len(my_history) == 0:
        donation_rate = 0.5  # neutral default
    else:
        donation_rate = sum(my_history) / len(my_history)  # True==1, False==0
    # Threshold decreases with own generosity and with round number.
    # More generous agents become more forgiving (lower threshold).
    threshold = max(0.1, 0.5 - 0.3 * donation_rate - 0.01 * round_num)
    return recipient_reputation > threshold
